This is a heuristic solution, not an optimal one. It pairs the vertical photos, orders the slides greedily, and keeps a fixed time budget.

**Approach**

1. **Tag IDs.** Map each tag string to an integer and keep each photo's tags as a sorted vector.
2. **Vertical pairing.** Sort the vertical photos by tag count and pair them so that the unions are large and well balanced. The simple version pairs the i-th with the (n-1-i)-th in sorted order, so one small photo goes with one large one, which tends to equalize slide sizes. Pairing photos that share no tags would maximize the union, but that costs more to check.
3. **Slide ordering.** Build slides (a single horizontal photo or a pair of vertical photos) with sorted tag vectors. Order them greedily, starting from slide 0 and repeatedly choosing the best next slide among a limited set of candidates.
4. **Candidate search.** Use an inverted index from tag to slides. To keep the cost bounded, take the unused slides from the posting lists of the current slide's tags, scanning at most about 200 candidates in total. Prefer rarer tags, with a per-tag cap, and remove used slides lazily. If no candidates are found, take any unused slide through a pointer that advances over the used ones.
5. **Scoring.** The score of a transition is min(common, a-common, b-common), computed by merging the two sorted tag vectors.
6. **Candidate selection.** Pick the candidate with the best score. Stop early if a candidate reaches the ideal of about half of the smaller slide size, since that is the maximum possible.
7. **Posting lists.** Sort the tags in each list so that the scan uses the lists in order of increasing size, and scan each list from a moving start pointer so that dead entries are skipped. For simplicity, each list is scanned up to a cap of 50 live entries per tag, with a total candidate limit of about 300. Dead entries at the front of a list are popped through a head index per list.

For N = 1e5 and about 300 candidates per step with merges over about 20 tags each, the cost is roughly 1e5 × 300 × 40 = 1.2e9 basic operations in the worst case. To be safe, the candidate limit is reduced to 150 and the time is checked. If more than 8 seconds have elapsed, the limit drops to 5.

```cpp
#include <bits/stdc++.h>
using namespace std;
int main(){
    ios::sync_with_stdio(false);cin.tie(nullptr);
    int n;cin>>n;
    unordered_map<string,int> mp;
    vector<vector<int>> t(n);
    vector<char> o(n);
    for(int i=0;i<n;i++){
        string s;int m;cin>>s>>m;o[i]=s[0];
        for(int j=0;j<m;j++){
            string x;cin>>x;
            auto it=mp.find(x);
            int id;
            if(it==mp.end()){id=mp.size();mp[x]=id;}else id=it->second;
            t[i].push_back(id);
        }
        sort(t[i].begin(),t[i].end());
    }
    vector<int> vs;
    vector<vector<int>> slides;
    vector<array<int,2>> ph;
    for(int i=0;i<n;i++){
        if(o[i]=='H'){slides.push_back(t[i]);ph.push_back({i,-1});}
        else vs.push_back(i);
    }
    sort(vs.begin(),vs.end(),[&](int a,int b){
        if(t[a].size()!=t[b].size())return t[a].size()<t[b].size();
        return a<b;});
    int k=vs.size();
    for(int i=0;i<k/2;i++){
        int a=vs[i],b=vs[k-1-i];
        vector<int> u;
        set_union(t[a].begin(),t[a].end(),t[b].begin(),t[b].end(),back_inserter(u));
        slides.push_back(u);ph.push_back({a,b});
    }
    int S=slides.size();
    if(S==0){printf("1\n%d\n",vs.empty()?0:vs[0]);return 0;}
    int T=mp.size();
    vector<vector<int>> post(T);
    for(int i=0;i<S;i++)for(int x:slides[i])post[x].push_back(i);
    vector<int> head(T,0);
    vector<char> used(S,0);
    auto score=[&](int a,int b){
        auto&A=slides[a];auto&B=slides[b];
        int i=0,j=0,c=0;
        while(i<(int)A.size()&&j<(int)B.size()){
            if(A[i]==B[j]){c++;i++;j++;}
            else if(A[i]<B[j])i++;else j++;
        }
        return min(c,min((int)A.size()-c,(int)B.size()-c));
    };
    auto st=chrono::steady_clock::now();
    vector<int> order;order.reserve(S);
    int cur=0;used[0]=1;order.push_back(0);
    int ptr=0;
    for(int step=1;step<S;step++){
        double el=chrono::duration<double>(chrono::steady_clock::now()-st).count();
        int lim=el>8?5:150;
        int best=-1,bs=-1;
        int cnt=0;
        auto&A=slides[cur];
        int target=A.size()/2;
        for(int x:A){
            auto&p=post[x];
            int&h=head[x];
            while(h<(int)p.size()&&used[p[h]])h++;
            int seen=0;
            for(int q=h;q<(int)p.size()&&seen<20;q++){
                int c=p[q];
                if(used[c])continue;
                seen++;cnt++;
                int sc=score(cur,c);
                if(sc>bs){bs=sc;best=c;}
            }
            if(cnt>=lim||bs>=target)break;
        }
        if(best<0){
            while(used[ptr])ptr++;
            best=ptr;
        }
        used[best]=1;order.push_back(best);cur=best;
    }
    string out=to_string(S)+"\n";
    for(int s:order){
        out+=to_string(ph[s][0]);
        if(ph[s][1]>=0)out+=" "+to_string(ph[s][1]);
        out+="\n";
    }
    fputs(out.c_str(),stdout);
}
```

The time check uses the wall clock, so the output can vary slightly between runs if the 8-second threshold is hit. On typical inputs it finishes well before that.
